-- 0064: complete the feature-specific walkthrough library.
--
-- Adds tours for the six areas the starter library did not cover: setup, AQi usage, CRM
-- tasks, automations, Website Studio and analytics. Definitions are generated from
-- src/lib/aqi/tutorials.ts and validated against the approved route/target registries.
--
-- No schema change. Existing tutorials and progress are untouched. A rollback is provided
-- in supabase/rollbacks/0064_aqi_feature_tours.down.sql.

insert into aqi_tutorials (slug, title, description, category, audience, route_prefix, priority, status)
select slug, title, description, category, audience, route_prefix, priority, 'published'
from jsonb_to_recordset($seed$[{"slug":"setup-workspace","title":"Finishing your setup","description":"Understand setup progress and the few steps that need you.","category":"Getting started","audience":["owner","admin","member","sales_rep","support","viewer","appointment_setter"],"route_prefix":"/setup","priority":15,"definition":{"title":"Finishing your setup","description":"Understand setup progress and the few steps that need you.","category":"Getting started","roles":["owner","admin","member","sales_rep","support","viewer","appointment_setter"],"routePrefix":"/setup","priority":15,"aliases":["finish setup","setup center","onboarding checklist","what do i need to do","activate workspace"],"keywords":["setup","onboarding","checklist","progress","activate","tasks"],"steps":[{"key":"progress","title":"This is your setup center","body":"Progress and the tasks that need you come from the real setup record. Technical steps are marked complete only after verification.","targetId":"setup.hero","route":"/setup"},{"key":"journey","title":"Three stages","body":"iAcquire prepares the system, you complete the steps that need your input, then the agency does a final review before activation.","targetId":"setup.journey","route":"/setup"}],"completion":{"kind":"finish"}}},{"slug":"ask-aqi","title":"Using AQi","description":"Find AQi, ask about the page you are on, and understand its access.","category":"AQi","audience":["owner","admin","member","sales_rep","support","viewer","appointment_setter"],"route_prefix":"/overview","priority":25,"definition":{"title":"Using AQi","description":"Find AQi, ask about the page you are on, and understand its access.","category":"AQi","roles":["owner","admin","member","sales_rep","support","viewer","appointment_setter"],"routePrefix":"/overview","priority":25,"aliases":["how do i use aqi","ai assistant","ask ai","open aqi","aqi help"],"keywords":["aqi","assistant","ai","chat","help","question"],"steps":[{"key":"launcher","title":"AQi is always here","body":"Open AQi from any workspace page. It answers from the pages and knowledge your role can already access; it never grants extra access.","targetId":"aqi.launcher","route":"/overview"}],"completion":{"kind":"finish"}}},{"slug":"manage-tasks","title":"Working with tasks","description":"See your follow-ups, choose whose work to view and create a real task.","category":"CRM","audience":["owner","admin","member","sales_rep","support","appointment_setter"],"route_prefix":"/crm/tasks","priority":45,"definition":{"title":"Working with tasks","description":"See your follow-ups, choose whose work to view and create a real task.","category":"CRM","roles":["owner","admin","member","sales_rep","support","appointment_setter"],"routePrefix":"/crm/tasks","priority":45,"aliases":["manage tasks","my tasks","assign a task","overdue tasks","task list"],"keywords":["tasks","follow-up","follow up","assignment","overdue","todo"],"steps":[{"key":"tasks-nav","title":"Open CRM Tasks","body":"Tasks is under CRM in the main navigation. Select it to continue.","targetId":"nav.crm.tasks","route":null,"advance":"click"},{"key":"queue","title":"Everything your team owes","body":"Tasks come from contacts, deals and automations. Overdue work is counted from the live records, not estimated.","targetId":"crm.tasks.header","route":"/crm/tasks"},{"key":"views","title":"Choose whose work","body":"Mine, team, overdue, upcoming and completed views use live task records. Assignment is changed on the task itself.","targetId":"crm.tasks.views","route":"/crm/tasks"},{"key":"create","title":"Create a task","body":"New task assigns a real person and a due date. AQi never creates or completes one for you.","targetId":"crm.tasks.new","route":"/crm/tasks"}],"completion":{"kind":"finish"}}},{"slug":"build-workflow","title":"Building an automation","description":"Read a workflow's real state and start a draft from a template or blank.","category":"Automation","audience":["owner","admin"],"route_prefix":"/crm/workflows","priority":55,"definition":{"title":"Building an automation","description":"Read a workflow's real state and start a draft from a template or blank.","category":"Automation","roles":["owner","admin"],"routePrefix":"/crm/workflows","priority":55,"aliases":["build a workflow","automation","automate follow up","new workflow","workflow builder"],"keywords":["workflow","automation","trigger","action","follow-up","new lead"],"steps":[{"key":"header","title":"Workflows are your automations","body":"Each workflow starts with a real event and runs the steps shown. Nothing sends until an owner approves that exact version.","targetId":"crm.workflows.header","route":"/crm/workflows"},{"key":"list","title":"Read the real state","body":"Status, last run and failures come from recorded runs. Archived workflows stay out of the default view.","targetId":"crm.workflows.list","route":"/crm/workflows"},{"key":"new","title":"Start from a template or blank","body":"Templates create a draft you can inspect. AQi never turns a workflow on for you.","targetId":"crm.workflows.new","route":"/crm/workflows"}],"completion":{"kind":"finish"}}},{"slug":"manage-website","title":"Your website","description":"Find the website overview and understand the private draft and publishing.","category":"Website","audience":["owner","admin"],"route_prefix":"/website","priority":75,"definition":{"title":"Your website","description":"Find the website overview and understand the private draft and publishing.","category":"Website","roles":["owner","admin"],"routePrefix":"/website","priority":75,"aliases":["website studio","edit my website","publish website","my website","change website"],"keywords":["website","site","publish","editor","domain","draft"],"steps":[{"key":"website-nav","title":"Open Website","body":"Website is in the main navigation. Select it to continue.","targetId":"nav.website","route":null,"advance":"click"},{"key":"overview","title":"Your website, under your control","body":"Status, style and publication come from the real site record. If no site exists, Choose a style starts one; otherwise Edit website opens your private draft. AQi never publishes it for you.","targetId":"website.hero","route":"/website"}],"completion":{"kind":"finish"}}},{"slug":"read-analytics","title":"Reading your analytics","description":"Choose a reporting period and read recorded results honestly.","category":"Analytics","audience":["owner","admin","member","sales_rep","support","viewer","appointment_setter"],"route_prefix":"/analytics","priority":85,"definition":{"title":"Reading your analytics","description":"Choose a reporting period and read recorded results honestly.","category":"Analytics","roles":["owner","admin","member","sales_rep","support","viewer","appointment_setter"],"routePrefix":"/analytics","priority":85,"aliases":["read analytics","reporting","performance report","analytics page","export report"],"keywords":["analytics","reporting","metrics","export","performance","range"],"steps":[{"key":"range","title":"Choose the period","body":"The date range applies to every metric below. Export downloads the underlying records your role can see.","targetId":"analytics.range","route":"/analytics"},{"key":"report","title":"Recorded results only","body":"Lead, execution and CRM numbers come from recorded records. A missing source is labelled unavailable, not zero.","targetId":"analytics.report","route":"/analytics"}],"completion":{"kind":"finish"}}}]$seed$::jsonb) as x(
  slug text, title text, description text, category text, audience text[], route_prefix text, priority integer
)
on conflict (slug) do nothing;

insert into aqi_tutorial_versions (tutorial_id, version, status, definition, notes, published_at)
