 here","body":"Open AQi from any workspace page. It answers from the pages and knowledge your role can already access; it never grants extra access.","targetId":"aqi.launcher","route":"/overview"}],"completion":{"kind":"finish"}}},{"slug":"manage-tasks","title":"Working with tasks","description":"See your follow-ups, choose whose work to view and create a real task.","category":"CRM","audience":["owner","admin","member","sales_rep","support","appointment_setter"],"route_prefix":"/crm/tasks","priority":45,"definition":{"title":"Working with tasks","description":"See your follow-ups, choose whose work to view and create a real task.","category":"CRM","roles":["owner","admin","member","sales_rep","support","appointment_setter"],"routePrefix":"/crm/tasks","priority":45,"aliases":["manage tasks","my tasks","assign a task","overdue tasks","task list"],"keywords":["tasks","follow-up","follow up","assignment","overdue","todo"],"steps":[{"key":"tasks-nav","title":"Open CRM Tasks","body":"Tasks is under CRM in the main navigation. Select it to continue.","targetId":"nav.crm.tasks","route":null,"advance":"click"},{"key":"queue","title":"Everything your team owes","body":"Tasks come from contacts, deals and automations. Overdue work is counted from the live records, not estimated.","targetId":"crm.tasks.header","route":"/crm/tasks"},{"key":"views","title":"Choose whose work","body":"Mine, team, overdue, upcoming and completed views use live task records. Assignment is changed on the task itself.","targetId":"crm.tasks.views","route":"/crm/tasks"},{"key":"create","title":"Create a task","body":"New task assigns a real person and a due date. AQi never creates or completes one for you.","targetId":"crm.tasks.new","route":"/crm/tasks"}],"completion":{"kind":"finish"}}},{"slug":"build-workflow","title":"Building an automation","description":"Read a workflow's real state and start a draft from a template or blank.","category":"Automation","audience":["owner","admin"],"route_prefix":"/crm/workflows","priority":55,"definition":{"title":"Building an automation","description":"Read a workflow's real state and start a draft from a template or blank.","category":"Automation","roles":["owner","admin"],"routePrefix":"/crm/workflows","priority":55,"aliases":["build a workflow","automation","automate follow up","new workflow","workflow builder"],"keywords":["workflow","automation","trigger","action","follow-up","new lead"],"steps":[{"key":"header","title":"Workflows are your automations","body":"Each workflow starts with a real event and runs the steps shown. Nothing sends until an owner approves that exact version.","targetId":"crm.workflows.header","route":"/crm/workflows"},{"key":"list","title":"Read the real state","body":"Status, last run and failures come from recorded runs. Archived workflows stay out of the default view.","targetId":"crm.workflows.list","route":"/crm/workflows"},{"key":"new","title":"Start from a template or blank","body":"Templates create a draft you can inspect. AQi never turns a workflow on for you.","targetId":"crm.workflows.new","route":"/crm/workflows"}],"completion":{"kind":"finish"}}},{"slug":"manage-website","title":"Your website","description":"Find the website overview and understand the private draft and publishing.","category":"Website","audience":["owner","admin"],"route_prefix":"/website","priority":75,"definition":{"title":"Your website","description":"Find the website overview and understand the private draft and publishing.","category":"Website","roles":["owner","admin"],"routePrefix":"/website","priority":75,"aliases":["website studio","edit my website","publish website","my website","change website"],"keywords":["website","site","publish","editor","domain","draft"],"steps":[{"key":"website-nav","title":"Open Website","body":"Website is in the main navigation. Select it to continue.","targetId":"nav.website","route":null,"advance":"click"},{"key":"overview","title":"Your website, under your control","body":"Status, style and publication come from the real site record. If no site exists, Choose a style starts one; otherwise Edit website opens your private draft. AQi never publishes it for you.","targetId":"website.hero","route":"/website"}],"completion":{"kind":"finish"}}},{"slug":"read-analytics","title":"Reading your analytics","description":"Choose a reporting period and read recorded results honestly.","category":"Analytics","audience":["owner","admin","member","sales_rep","support","viewer","appointment_setter"],"route_prefix":"/analytics","priority":85,"definition":{"title":"Reading your analytics","description":"Choose a reporting period and read recorded results honestly.","category":"Analytics","roles":["owner","admin","member","sales_rep","support","viewer","appointment_setter"],"routePrefix":"/analytics","priority":85,"aliases":["read analytics","reporting","performance report","analytics page","export report"],"keywords":["analytics","reporting","metrics","export","performance","range"],"steps":[{"key":"range","title":"Choose the period","body":"The date range applies to every metric below. Export downloads the underlying records your role can see.","targetId":"analytics.range","route":"/analytics"},{"key":"report","title":"Recorded results only","body":"Lead, execution and CRM numbers come from recorded records. A missing source is labelled unavailable, not zero.","targetId":"analytics.report","route":"/analytics"}],"completion":{"kind":"finish"}}}]$seed$::jsonb) as x(slug text, definition jsonb)
join aqi_tutorials t on t.slug = x.slug
on conflict (tutorial_id, version) do nothing;

update aqi_tutorials t
set published_version_id = v.id, updated_at = now()
from aqi_tutorial_versions v
where v.tutorial_id = t.id and v.version = 1 and t.published_version_id is null
  and t.slug in ('setup-workspace', 'ask-aqi', 'manage-tasks', 'build-workflow', 'manage-website', 'read-analytics');

-- Contextual entry points so the new tours are discoverable on their real pages.
insert into aqi_contextual_tips (slug, route_prefix, title, body, roles, permission, tutorial_slug, priority)
values
  ('setup-help', '/setup', 'Need help with setup?', 'See what is already done, what needs you, and what the final agency review covers.', '{}', 'setup.view', 'setup-workspace', 35),
  ('aqi-help', '/overview', 'New to AQi?', 'AQi answers from the pages and knowledge you can already access. This short guide shows where it lives.', '{}', null, 'ask-aqi', 25),
  ('tasks-help', '/crm/tasks', 'Need help with tasks?', 'See how your task views work and where a new task assigns a real person and due date.', '{}', 'crm.view', 'manage-tasks', 45),
  ('workflows-help', '/crm/workflows', 'Want to build an automation?', 'Read a workflow''s real status, then start a draft from a template or blank. Nothing sends until approval.', '{owner,admin}', 'workflows.view', 'build-workflow', 55),
  ('website-help', '/website', 'Need help with your website?', 'See the real status, where the private draft is edited, and how publication stays under your control.', '{owner,admin}', 'website.view', 'manage-website', 75),
  ('analytics-help', '/analytics', 'Need help reading this report?', 'Choose a real reporting period and see which results come from recorded records.', '{}', 'analytics.view', 'read-analytics', 85)
on conflict (slug) do nothing;
